package com.aetherforge.repo;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class MachineRepository {private final JdbcTemplate db;public MachineRepository(JdbcTemplate db){this.db=db;}public List<Map<String,Object>> list(String q,String status){return db.queryForList("select m.id,m.code,m.name,m.machine_type,m.status,m.health,m.failure_probability,m.rul_hours,m.last_maintenance,pl.code line_code,pl.name line_name from machine m join production_line pl on pl.id=m.line_id where (? is null or lower(m.code||' '||m.name) like lower('%'||?||'%')) and (? is null or m.status=?) order by m.code",q,q,status,status);}public Map<String,Object> one(String id){return db.queryForMap("select m.*,pl.code line_code,pl.name line_name,f.name factory_name from machine m join production_line pl on pl.id=m.line_id join factory f on f.id=m.factory_id where m.id::text=?",id);}public List<Map<String,Object>> sensors(String id,int minutes){return db.queryForList("select s.id,s.code,s.kind,s.unit,r.recorded_at,r.value from sensor s join lateral (select recorded_at,value from sensor_reading r where r.sensor_id=s.id and r.recorded_at>now()-make_interval(mins=>?) order by r.recorded_at desc limit 120) r on true where s.machine_id::text=? order by s.kind,r.recorded_at",minutes,id);}public Map<String,Object> metrics(){return db.queryForMap("select coalesce(round(avg(health),1),0) health,coalesce(round(avg(failure_probability)*100,1),0) risk,coalesce(sum(case when status='RUNNING' then 1 else 0 end),0) running,count(*) machines from machine");}}
